\reviewer{Several relevant references are missing from the related work discussion.}

\response{We have added Sellam et al.\ (ICLR 2022; MultiBERTs) and Fehlauer et al.\ (EMNLP 2025) to the Related Work section (\S2). Additional references are under verification and will be incorporated if confirmed before the camera-ready deadline.}

\location{\S2 (``Underspecification and Model Agreement'' paragraph), \texttt{references.bib}.}

\end{document}

